/* Handout values and figures checked in D2L on 2026-09-28.
 * Original worked explanations; manual edition mappings remain in solutions-data.js. */
const r=String.raw, out=[];
const topics={3:'Electric flux',5:'Electric potential and energy',6:'Potential and capacitance',7:'Capacitors and dielectrics',8:'Current and resistance',9:'DC and RC circuits',10:'Magnetic forces',11:'Magnetic force and torque',12:'Sources of magnetic fields',13:'Induction and inductance'};
function add(h,p,title,given,find,identify,setup,execute,evaluate,result,kind,labels,answer,unit){out.push({id:(h===7&&p==='24.7'?'hw7-':'')+p.replace('.','-'),problem:p,homework:h,title:p+' · '+title,topic:topics[h],prompt:given+' '+find,given,find,variables:'Symbols and directions are defined in the setup and diagram. Use SI units; k = 8.988 × 10⁹, ε₀ = 8.854 × 10⁻¹², μ₀ = 4π × 10⁻⁷, e = 1.602 × 10⁻¹⁹.',hint:identify,steps:[['Identify',identify],['Set up',setup],['Execute',execute],['Evaluate',evaluate]],result,kind,labels,answer,unit});}
add(3,'22.1','Flux through a flat sheet','A = 0.250 m²; E = 14 N/C; angle from the surface normal = 60°.','Find flux magnitude, dependence on shape, and angles for largest/smallest magnitude.','Flux uses the normal angle, not the angle to the sheet.',r`$\Phi=EA\cos\theta$.`,r`$|\Phi|=(14)(0.250)\cos60^\circ=1.75\ \mathrm{N\,m^2/C}$.`,'Shape does not matter for a flat sheet in a uniform field. Magnitude is largest at 0° or 180° and zero at 90°.','1.75 N m²/C; maximum at 0°/180°, minimum at 90°.','flux',['θ = 60°','A = 0.250 m²','E = 14 N/C'],1.75,'N m²/C');
add(3,'22.2','Angle measured from the plane','Rectangle 0.400 m × 0.600 m; E = 90.0 N/C at 20° to its plane.','Find electric-flux magnitude.','Convert the plane angle to a normal angle.',r`$A=0.400(0.600),\ \theta=90^\circ-20^\circ=70^\circ$.`,r`$|\Phi|=90.0(0.240)\cos70^\circ=7.39\ \mathrm{N\,m^2/C}$.`,'A field almost parallel to the sheet gives less flux than EA.','7.39 N m²/C.','flux',['θnormal = 70°','20° to plane','A = 0.240 m²'],7.39,'N m²/C');
add(3,'22.5','Flux through a hemisphere','A hemisphere of radius r has its symmetry axis parallel to a uniform field E.','Find the flux through its curved surface.','Close the hemisphere with a flat disk; no charge is enclosed.',r`$\Phi_{curved}+\Phi_{disk}=0,\quad A_{disk}=\pi r^2$.`,r`For the dome pointing along E, $\Phi_{disk}=-E\pi r^2$, hence $\Phi_{curved}=+E\pi r^2$.`,'Reverse the dome orientation and the signed flux reverses. Its magnitude uses projected disk area, not curved area 2πr².','|Φ| = Eπr²; positive for the outward-facing dome along E.','hemisphere',['Uniform E →','Radius r','Close with a disk']);
add(3,'22.6','Flux through six cube faces','Cube side L = 0.100 m; E = 4.00 × 10³ N/C in the xy-plane at 53.1° from +x toward +y. S₁/S₃ are −y/+y; S₂/S₄ are ±z; S₅/S₆ are +x/−x.','Find each face flux and total.','Dot E with each outward face normal.',r`$E_x=E\cos53.1^\circ=2400,\ E_y=E\sin53.1^\circ=3200,\ E_z=0;\ A=L^2=0.0100$.`,r`$(\Phi_1,\Phi_2,\Phi_3,\Phi_4,\Phi_5,\Phi_6)=(-32,0,+32,0,+24,-24)\ \mathrm{N\,m^2/C}$.`,'Opposite faces cancel because the field is uniform. Net enclosed charge is zero.','Net flux = 0; face fluxes −32, 0, +32, 0, +24, −24 N m²/C.','cube',['Ex = 2400 N/C','Ey = 3200 N/C','Ez = 0']);
add(3,'22.8','Flux counts enclosed charge','q₁ = +4.00 nC; q₂ = −7.80 nC; q₃ = +2.40 nC. S₁ encloses q₁; S₂ q₂; S₃ q₁+q₂; S₄ q₁+q₃; S₅ all three.','Find each outward flux and whether redistribution changes it.','Gauss’s law depends on total enclosed charge.',r`$\Phi=Q_{enc}/\varepsilon_0$. Enclosed charges in order: $4.00,-7.80,-3.80,6.40,-1.40\ \mathrm{nC}$.`,r`$(\Phi_1,\Phi_2,\Phi_3,\Phi_4,\Phi_5)=(452,-881,-429,723,-158)\ \mathrm{N\,m^2/C}$.`,'Redistributing charge within each sphere changes local fields but not these fluxes, provided the same charges remain enclosed.','452, −881, −429, 723, −158 N m²/C, respectively.','charges',['q₁ = +4.00 nC','q₂ = −7.80 nC','q₃ = +2.40 nC'],452,'N m²/C, S₁');
add(3,'22.9','Charged paint on a sphere','A uniform thin paint layer on a plastic sphere of diameter 0.120 m carries Q = −49.0 µC.','Find E just inside, just outside, and 0.0500 m beyond the surface.','Spherical symmetry makes the shell field zero inside and point-like outside.',r`$R=0.0600\ \mathrm m;\ E(r<R)=0;\ |E(r>R)|=k|Q|/r^2$.`,r`$E(R^-)=0;\ |E(R^+)|=1.22\times10^8\ \mathrm{N/C};\ |E(0.110)|=3.64\times10^7\ \mathrm{N/C}$.`,'Both exterior fields point inward. Use 0.110 m from the centre for the last part.','0; 1.22 × 10⁸ N/C inward; 3.64 × 10⁷ N/C inward.','shell',['Q = −49.0 µC','R = 0.0600 m','Outside E inward'],1.22e8,'N/C, just outside');
add(5,'23.1','Work along a two-dimensional move','Fixed q₁ = +2.40 µC at the origin; q₂ = −4.30 µC moves from (0.150, 0) m to (0.250, 0.250) m.','Find work done by the electric force.','Electric work equals initial minus final potential energy.',r`$r_i=0.150,\ r_f=\sqrt{0.250^2+0.250^2};\ W=kq_1q_2(1/r_i-1/r_f)$.`,r`$r_f=0.3536\ \mathrm m;\ W=(8.988\times10^9)(2.40\times10^{-6})(-4.30\times10^{-6})(6.667-2.828)=-0.356\ \mathrm J$.`,'Moving unlike charges apart raises potential energy; electric work is negative.','−0.356 J.','pair',['q₁ fixed at origin','ri = 0.150 m','rf = 0.3536 m'],-.356,'J');
add(5,'23.5','Closest approach of repelling charges','Fixed q₁ = −2.80 µC; moving q₂ = −7.80 µC, m = 1.50 g, initially 0.800 m away at 22.0 m/s toward q₁.','Find speed at 0.400 m and minimum separation.','Repulsion converts kinetic energy into electric potential energy.',r`$\tfrac12mv^2+kq_1q_2/r=\tfrac12mv_i^2+kq_1q_2/r_i=E_{tot}$.`,r`$E_{tot}=0.363+0.2454=0.6084\ \mathrm J$. At $r=0.400$, $K=0.1177\ \mathrm J$, so $v=12.5\ \mathrm{m/s}$. At turnaround $K=0$, $r_{min}=kq_1q_2/E_{tot}=0.323\ \mathrm m$.`,'The turning point is closer than 0.400 m, so the intermediate speed is real and smaller than 22 m/s.','12.5 m/s; minimum separation 0.323 m.','pair',['Both charges negative','Approaching: vᵢ = 22 m/s','Turning point: v = 0'],12.5,'m/s at 0.400 m');
add(5,'23.7','Two protons approaching head-on','Two protons start far apart, each moving at 2.00 × 10⁵ m/s toward the other in the Earth frame; mₚ = 1.673 × 10⁻²⁷ kg.','Find their maximum repulsive force.','Both protons contribute kinetic energy, and both stop momentarily at closest approach.',r`$K_{total}=2(\tfrac12m_pv^2)=m_pv^2=k e^2/r_{min};\ F_{max}=ke^2/r_{min}^2$.`,r`$r_{min}=3.45\times10^{-12}\ \mathrm m;\ F_{max}=1.94\times10^{-5}\ \mathrm N$.`,'Using only one proton’s kinetic energy would give twice the separation and one-quarter the force.','Maximum force 1.94 × 10⁻⁵ N.','pair',['+e →','← +e','Both initially 2.00 × 10⁵ m/s'],1.94e-5,'N');
add(5,'23.8','Energy of three equal charges','Three charges q = +1.20 µC occupy an equilateral triangle of side a = 0.400 m.','Find the energy relative to infinite separation.','Count distinct pairs once: there are three.',r`$U=\sum_{i<j}kq_iq_j/r_{ij}=3kq^2/a$.`,r`$U=3(8.988\times10^9)(1.20\times10^{-6})^2/0.400=0.0971\ \mathrm J$.`,'The energy is positive: external work is required to assemble repelling charges.','0.0971 J.','triangle',['Each q = +1.20 µC','All sides a = 0.400 m','3 distinct pairs'],.0971,'J');
add(5,'23.19','Potentials at two points','q₁ = +2.40 nC and q₂ = −6.50 nC are 0.100 m apart. A is their midpoint; B is 0.0800 m from q₁ and 0.0600 m from q₂.','Find Vₐ, Vᵦ, and electric work moving +2.50 nC from B to A.','Potential is a signed scalar sum; work uses start minus finish.',r`$V=k(q_1/r_1+q_2/r_2);\ W_{B\to A}=q_t(V_B-V_A)$.`,r`$V_A=-737\ \mathrm V;\ V_B=-704\ \mathrm V;\ W=(2.50\times10^{-9})(32.96)=8.24\times10^{-8}\ \mathrm J$.`,'The positive test charge moves to lower potential, so the field does positive work.','Vₐ = −737 V; Vᵦ = −704 V; W = +8.24 × 10⁻⁸ J.','triangle',['A: 0.050 m from each','B: r₁ = 0.080 m','B: r₂ = 0.060 m'],-737,'V at A');
add(5,'23.27','Electron on a charged ring axis','Ring radius R = 0.150 m, charge Q = +24.0 nC. An electron starts at rest on its axis, x₀ = 0.300 m; constrain motion to the axis.','Describe motion and find the speed through the centre.','The attractive force restores the electron toward the ring plane.',r`$V(x)=kQ/\sqrt{R^2+x^2};\ \tfrac12m_ev^2=e[V(0)-V(x_0)]$.`,r`$V(0)=1438\ \mathrm V,\ V(x_0)=643\ \mathrm V;\ v=\sqrt{2e(795)/m_e}=1.67\times10^7\ \mathrm{m/s}$.`,'It oscillates between ±0.300 m, fastest at the centre. This finite-amplitude motion is not simple harmonic because force is not proportional to x.','Oscillatory motion; centre speed 1.67 × 10⁷ m/s.','ring',['R = 0.150 m','Q = +24.0 nC','Electron at x₀ = 0.300 m'],1.67e7,'m/s');
add(6,'23.44','Electric field from a potential','V = Ax²y − Bxy², with A = 5.00 V/m³ and B = 8.00 V/m³. Evaluate at (2.00, 0.400, 0) m.','Find E components, magnitude and direction.','Take the negative gradient, differentiating one coordinate at a time.',r`$E_x=-2Axy+By^2;\ E_y=-Ax^2+2Bxy;\ E_z=0$.`,r`$E_x=-8+1.28=-6.72;\ E_y=-20+12.8=-7.20\ \mathrm{V/m}$. $|E|=\sqrt{6.72^2+7.20^2}=9.85\ \mathrm{V/m}$; angle $=226.97^\circ$ from +x.`,'Both components are negative, so the vector is in quadrant III, not quadrant I.','E = (−6.72 i − 7.20 j) V/m; 9.85 V/m at 227°.','axes',['Ex = −6.72 V/m','Ey = −7.20 V/m','Ez = 0'],9.85,'V/m, magnitude');
add(6,'23.55','Nonuniform field in a diode','V(x) = Cx^(4/3); cathode x = 0, anode x = d = 0.0130 m; anode voltage 240 V.','Find C, E(x), and electron force at x = d/2.','Differentiate V rather than assuming a uniform 240/d field.',r`$C=240/d^{4/3};\ E_x=-dV/dx=-\tfrac43Cx^{1/3};\ F_x=-eE_x$.`,r`$C=7.85\times10^4\ \mathrm{V/m^{4/3}};\ E_x=-(1.047\times10^5)x^{1/3}\ \mathrm{V/m}$ (x in metres). At 0.00650 m, $E_x=-1.954\times10^4\ \mathrm{V/m}$ and $F_x=+3.13\times10^{-15}\ \mathrm N$.`,'Field points toward the cathode; the negative electron feels force toward the anode.','C = 7.85 × 10⁴ V/m^(4/3); midpoint force +3.13 × 10⁻¹⁵ N.','plates',['Cathode: x = 0','Anode: x = 0.013 m','E ← ; electron force →'],3.13e-15,'N, electron force along +x');
add(6,'23.59','Hanging charge between plates','A 1.50 g ball with q = +8.90 µC hangs at 30.0° from vertical between plates separated by d = 0.0500 m.','Find the potential-difference magnitude.','Divide horizontal by vertical force balance.',r`$T\sin\theta=qE,\ T\cos\theta=mg;\ E=mg\tan\theta/q;\ |\Delta V|=Ed$.`,r`$E=(0.00150)(9.80)\tan30^\circ/(8.90\times10^{-6})=954\ \mathrm{N/C};\ |\Delta V|=47.7\ \mathrm V$.`,'The positive ball deflects along E, toward the lower-potential plate.','47.7 V.','pendulum',['θ = 30°','qE horizontal','mg downward'],47.7,'V');
add(6,'24.1','Vacuum parallel plates','Plate gap d = 2.50 mm; charge magnitude Q = 80.0 nC on each plate; field E = 4.00 × 10⁶ V/m.','Find voltage, plate area and capacitance.','Use the field between two oppositely charged plates.',r`$V=Ed;\ A=Q/(\varepsilon_0 E);\ C=Q/V$.`,r`$V=1.00\times10^4\ \mathrm V;\ A=2.26\times10^{-3}\ \mathrm{m^2};\ C=8.00\times10^{-12}\ \mathrm F$.`,'C also equals ε₀A/d. Q is the magnitude on one plate, not the sum of magnitudes.','10.0 kV; 22.6 cm²; 8.00 pF.','plates',['Gap d = 2.50 mm','Q = ±80.0 nC','E = 4.00 × 10⁶ V/m'],1e4,'V');
add(6,'24.3','Capacitor geometry and field','Air capacitor C = 245 pF, Q = 0.148 µC, separation d = 0.328 mm.','Find voltage, area, field magnitude and surface charge density.','Combine Q = CV with C = ε₀A/d.',r`$V=Q/C;\ A=Cd/\varepsilon_0;\ E=V/d;\ |\sigma|=Q/A$.`,r`$V=604\ \mathrm V;\ A=9.08\times10^{-3}\ \mathrm{m^2};\ E=1.84\times10^6\ \mathrm{V/m};\ |\sigma|=1.63\times10^{-5}\ \mathrm{C/m^2}$.`,'The two plate densities have opposite signs. Check σ = ε₀E independently.','604 V; 90.8 cm²; 1.84 × 10⁶ V/m; ±1.63 × 10⁻⁵ C/m².','plates',['C = 245 pF','d = 0.328 mm','Q = ±0.148 µC'],604,'V');
for(const h of [6,7])add(h,'24.7','Changing capacitor separation','Air capacitor: Q = 240 pC, V = 42.0 V, plate area A = 6.80 cm².','Find gap d, then voltage for the same Q if d doubles.','At fixed charge, doubling separation halves capacitance.',r`$C=Q/V=5.71\ \mathrm{pF};\ d=\varepsilon_0 A/C;\ V'=Q/(C/2)=2V$.`,r`$d=(8.854\times10^{-12})(6.80\times10^{-4})/(5.714\times10^{-12})=1.05\times10^{-3}\ \mathrm m;\ V'=84.0\ \mathrm V$.`,'The field stays constant because Q/A is unchanged; voltage grows with gap. This question appears in both Homework 6 and 7.','d = 1.05 mm; new voltage 84.0 V.','plates',['A = 6.80 cm²','Fixed Q = 240 pC','d doubles → V doubles'],.00105,'m, initial gap');
add(7,'24.8','Design an air capacitor','Circular air capacitor C = 5.00 pF must withstand 100 V while E ≤ 1.00 × 10⁴ N/C.','Find minimum gap, minimum plate radius, and maximum charge at 100 V.','Field limit sets d; required capacitance then sets area.',r`$d_{min}=V/E_{max};\ r_{min}=\sqrt{Cd_{min}/(\pi\varepsilon_0)};\ Q_{max}=CV$.`,r`$d_{min}=0.0100\ \mathrm m;\ r_{min}=0.0424\ \mathrm m;\ Q_{max}=5.00\times10^{-10}\ \mathrm C$.`,'Increasing d beyond its minimum requires larger plates to preserve C.','10.0 mm gap; 4.24 cm radius; 500 pC.','plates',['C = 5.00 pF','E ≤ 10⁴ N/C','Circular plates: radius r'],.0424,'m, minimum radius');
add(7,'24.12','Cylindrical capacitor','Coaxial air capacitor: inner radius a = 2.20 mm, outer inner radius b = 3.50 mm, length L = 2.80 m. Inner conductor is 0.350 V higher.','Find capacitance per length and charge on each conductor.','Integrate the radial field between coaxial conductors.',r`$V=\lambda\ln(b/a)/(2\pi\varepsilon_0);\ C/L=2\pi\varepsilon_0/\ln(b/a);\ Q=(C/L)LV$.`,r`$C/L=1.20\times10^{-10}\ \mathrm{F/m};\ Q=1.17\times10^{-10}\ \mathrm C$.`,'The inner conductor is positive and the outer negative; use the inner surface radius of the outer cylinder.','120 pF/m; inner +117 pC, outer −117 pC.','coax',['a = 2.20 mm','b = 3.50 mm','L = 2.80 m'],1.20e-10,'F/m');
add(7,'24.14','Series and parallel capacitors','Network A—10 µF—(5 µF in parallel with 8 µF)—9 µF—B; Vₐᵦ = 50.0 V.','Find equivalent capacitance, total stored plate charge, and charges on the 10 and 9 µF capacitors.','Combine the middle parallel group before the series chain.',r`$C_p=5+8=13\ \mu\mathrm F;\ C_{eq}^{-1}=10^{-1}+13^{-1}+9^{-1}$ (capacitances in µF).`,r`$C_{eq}=3.47\ \mu\mathrm F;\ Q=C_{eq}V=174\ \mu\mathrm C$. The series capacitors each carry this charge: $Q_{10}=Q_9=174\ \mu\mathrm C$.`,'The 5 and 8 µF branch charges add to the series charge; they are not individually equal to it.','Ceq = 3.47 µF; total, Q₁₀ and Q₉ = 174 µC each.','capnetwork',['10 µF','5 ∥ 8 = 13 µF','9 µF'],3.47,'µF, equivalent');
add(7,'24.24','Work pulling plates apart','Isolated capacitor C = 920 pF carries Q = 3.90 µC. Double the gap, keeping Q constant.','Find original and final voltages and external work.','Use U = Q²/(2C), since charge is fixed.',r`$V_i=Q/C;\ C_f=C/2;\ V_f=2V_i;\ W_{ext}=U_f-U_i=Q^2/(2C)$.`,r`$V_i=4.24\ \mathrm{kV};\ V_f=8.48\ \mathrm{kV};\ W_{ext}=8.27\times10^{-3}\ \mathrm J$.`,'Positive work separates attracting plates; the energy doubles.','4.24 kV → 8.48 kV; external work 8.27 mJ.','plates',['Isolated: fixed Q','d → 2d','C → C/2'],.00827,'J, external work');
add(7,'24.36','Build a paper capacitor','Target C = 1.00 nF. Paper κ = 3.0, sheet thickness 0.20 mm, plate dimensions 22 cm × 28 cm. Posterboard has thickness 12 mm and the same κ.','Find paper-sheet count, posterboard plate area, and how replacing paper with lower-κ Teflon changes required area.','Stacked paper increases dielectric thickness; use C = κε₀A/d.',r`$n=\kappa\varepsilon_0 A/(Ct);\ A_{board}=Cd/(\kappa\varepsilon_0)$.`,r`$n=3(8.854\times10^{-12})(0.22)(0.28)/[(10^{-9})(0.00020)]=8.18$. Use about 8 sheets (1.02 nF). $A_{board}=0.452\ \mathrm{m^2}$.`,'An integer number of sheets gives an approximate target. For the same thickness and capacitance, lower κ requires larger area.','About 8 sheets; posterboard area 0.452 m²; Teflon needs more area.','plates',['Paper stack: d = nt','κ = 3.0','A = 0.22 × 0.28 m²'],.452,'m², posterboard area');
add(7,'24.66','Half-filled dielectric capacitor','Square plates 0.120 m on a side, gap d = 4.50 mm; half the area contains Plexiglas κ = 3.40 and half air. Battery stays connected at 18.0 V.','Find C, stored energy, and energy after removing the dielectric.','Side-by-side areas are parallel capacitors at the same voltage.',r`$C=\varepsilon_0 A(1+\kappa)/(2d);\ U=CV^2/2;\ C_0=\varepsilon_0 A/d$.`,r`$C=62.3\ \mathrm{pF};\ U=1.01\times10^{-8}\ \mathrm J$. After removal $C_0=28.3\ \mathrm{pF}$ and $U_0=4.59\times10^{-9}\ \mathrm J$.`,'The battery fixes voltage, not charge. Using a series-dielectric formula would describe a different geometry.','62.3 pF; 10.1 nJ initially; 4.59 nJ after removal.','dielectric',['Half area: air','Half area: κ = 3.40','Battery holds 18.0 V'],62.3,'pF');
add(7,'24.68','Capacitive fuel gauge','Vertical plates have width w, height L and gap d. Fuel fills height h; air above it. κ = 1.95 for gasoline or 33.0 for methanol.','Derive effective dielectric constant; evaluate quarter, half and three-quarter full; compare sensitivity.','Fuel and air areas contribute in parallel.',r`$C=\varepsilon_0 w(L-h)/d+\kappa\varepsilon_0 wh/d;\ C/C_0=\kappa_{eff}=1+(\kappa-1)h/L$.`,r`For $h/L=1/4,1/2,3/4$: gasoline gives $1.2375,1.475,1.7125$; methanol gives $9,17,25$.`,'Both are linear in fill height in this ideal model. Methanol gives a larger capacitance change per unit height, making the change easier to resolve.','κeff = 1 + (κ − 1)h/L; methanol is more sensitive.','fuel',['Total height L','Fuel height h','Air above fuel']);
add(8,'25.1','Charge in a lightning pulse','Assume a constant 25,000 A current lasts 40 µs.','Find transferred charge.','Current is charge per unit time.',r`$Q=I\Delta t$.`,r`$Q=(2.50\times10^4)(40\times10^{-6})=1.0\ \mathrm C$.`,'Convert microseconds to seconds; this is the constant-current approximation.','1.0 C.','wire',['I = 25,000 A','Δt = 40 µs','Q = IΔt'],1,'C');
add(8,'25.2','Silver-wire drift speed','Wire diameter 2.6 mm; 420 C passes in 80 min; electron density n = 5.8 × 10²⁸ m⁻³.','Find current and electron drift-speed magnitude.','Use circular area and distinguish drift from signal speed.',r`$I=Q/t;\ A=\pi d^2/4;\ v_d=I/(neA)$.`,r`$I=420/4800=0.0875\ \mathrm A;\ A=5.31\times10^{-6}\ \mathrm{m^2};\ v_d=1.77\times10^{-6}\ \mathrm{m/s}$.`,'Electron drift is opposite conventional current and is very slow.','0.0875 A; drift speed 1.77 × 10⁻⁶ m/s.','wire',['Diameter 2.6 mm','Conventional I →','Electrons drift ←'],1.77e-6,'m/s');
add(8,'25.5','Transit time in two wire gauges','Copper length 0.710 m; I = 4.85 A; n = 8.5 × 10²⁸ m⁻³. Diameters are 2.05 mm and 4.12 mm.','Find electron transit time in each and explain diameter dependence.','At fixed current, a larger area needs a smaller drift speed.',r`$v_d=I/(ne\pi d^2/4);\ t=L/v_d=Lne\pi d^2/(4I)$.`,r`For 2.05 mm, $v_d=1.08\times10^{-4}\ \mathrm{m/s}$ and $t=6.58\times10^3\ \mathrm s=1.83\ \mathrm h$. For 4.12 mm, $v_d=2.67\times10^{-5}\ \mathrm{m/s}$ and $t=2.66\times10^4\ \mathrm s=7.38\ \mathrm h$.`,'v scales as 1/d² and transit time as d². This is electron drift, not how quickly a circuit responds.','1.83 h and 7.38 h; thicker wire gives slower drift.','wire',['L = 0.710 m','Same current: 4.85 A','t ∝ d²'],6580,'s, 2.05 mm wire');
add(8,'25.11','Temperature coefficient from current','Rod L = 1.50 m, diameter 0.00500 m, V = 15.0 V. Current is 18.5 A at 20.0°C and 17.2 A at 92.0°C; ignore expansion.','Find ρ₂₀ and α₂₀.','The fixed-voltage current decrease means resistance increased.',r`$\rho_{20}=(V/I_{20})A/L;\ R_{92}/R_{20}=I_{20}/I_{92}=1+\alpha(92-20)$.`,r`$\rho_{20}=1.06\times10^{-5}\ \Omega\mathrm m;\ \alpha=(18.5/17.2-1)/72=1.05\times10^{-3}\ \mathrm{K^{-1}}$.`,'Temperature differences in kelvins and Celsius have the same numerical value.','ρ₂₀ = 1.06 × 10⁻⁵ Ω m; α = 1.05 × 10⁻³ K⁻¹.','wire',['L = 1.50 m','Fixed V = 15.0 V','20°C → 92°C'],1.06e-5,'Ω m');
add(8,'25.12','Current density in square copper wire','Square side 2.3 mm; length 4.0 m; I = 3.6 A; n = 8.5 × 10²⁸ m⁻³; copper ρ = 1.72 × 10⁻⁸ Ω m.','Find current density, electric field, and electron transit time.','The cross-section is square, not circular.',r`$A=s^2;\ J=I/A;\ E=\rho J;\ v_d=J/(ne);\ t=Lne/J$.`,r`$A=5.29\times10^{-6}\ \mathrm{m^2};\ J=6.81\times10^5\ \mathrm{A/m^2};\ E=0.0117\ \mathrm{V/m};\ t=8.00\times10^4\ \mathrm s=22.2\ \mathrm h$.`,'A small internal electric field maintains a substantial current because copper has low resistivity.','6.81 × 10⁵ A/m²; 0.0117 V/m; 8.00 × 10⁴ s.','wire',['Square area s²','s = 2.3 mm','L = 4.0 m'],6.81e5,'A/m²');
add(8,'25.16','Stretching a wire','Wire resistance is R. Stretch it to 3L without changing density or resistivity.','Find its new resistance.','Fixed amount and density mean fixed volume LA.',r`$A'=LA/(3L)=A/3;\ R'=\rho(3L)/(A/3)$.`,r`$R'=9\rho L/A=9R$.`,'Both the longer path and smaller cross-section raise resistance, each by a factor of three.','9R.','wire',['L → 3L','A → A/3','Volume unchanged']);
add(8,'25.25','Transmission-line loss','Copper cable L = 100 km, diameter 0.100 m, I = 125 A; ρ = 1.72 × 10⁻⁸ Ω m.','Find voltage drop and thermal energy per hour.','Find resistance, then use V = IR and energy = I²Rt.',r`$R=\rho L/(\pi d^2/4);\ \Delta V=IR;\ E_{heat}=I^2R(3600)$.`,r`$R=0.219\ \Omega;\ \Delta V=27.4\ \mathrm V;\ P=3.42\ \mathrm{kW};\ E_{heat}=1.23\times10^7\ \mathrm J=3.42\ \mathrm{kWh}$.`,'This is the loss in the specified one cable; do not silently double its length.','27.4 V drop; 1.23 × 10⁷ J per hour.','wire',['L = 100 km','Diameter 0.100 m','I = 125 A'],27.4,'V');
add(8,'25.21','Gold wire under an electric field','Gold diameter 0.84 mm; E = 0.49 V/m; segment length 6.4 m; ρ = 2.44 × 10⁻⁸ Ω m.','Find current, voltage difference magnitude and segment resistance.','Microscopic Ohm’s law gives current density from field.',r`$J=E/\rho;\ I=J\pi d^2/4;\ |\Delta V|=EL;\ R=\rho L/A$.`,r`$I=11.1\ \mathrm A;\ |\Delta V|=3.14\ \mathrm V;\ R=0.282\ \Omega$.`,'Check IR = 3.14 V. Potential decreases along the field.','11.1 A; 3.14 V; 0.282 Ω.','wire',['E = 0.49 V/m','L = 6.4 m','Gold: ρ = 2.44 × 10⁻⁸ Ω m'],11.1,'A');
module.exports=out;
add(9,'26.3','Adding a series resistor','A 25.0 Ω resistor dissipates 36.0 W on an ideal battery. Add 15.0 Ω in series.','Find total power after the change.','The battery voltage stays fixed; the current does not.',r`$V=\sqrt{P_1R_1};\ R_{eq}=25+15;\ P_{new}=V^2/R_{eq}$.`,r`$V=30.0\ \mathrm V;\ I=30/40=0.750\ \mathrm A;\ P_{new}=900/40=22.5\ \mathrm W$.`,'Adding series resistance reduces total power for a fixed-voltage source.','22.5 W.','series',['30 V source','25 Ω + 15 Ω','I = 0.750 A'],22.5,'W');
add(9,'26.6','Find the source from an ammeter','45 Ω and 35 Ω are in series with a parallel group: 25 Ω (ammeter branch), 15 Ω, and (15 Ω + 10 Ω). Ideal ammeter reads 1.25 A; voltmeter spans 45 Ω.','Find voltmeter reading and battery emf.','The ammeter fixes the shared parallel voltage.',r`$V_p=(1.25)(25)=31.25\ \mathrm V;\ I_{total}=V_p(1/25+1/15+1/25)$.`,r`$I_{total}=4.583\ \mathrm A;\ V_{meter}=45I=206.25\ \mathrm V;\ \mathcal E=I(45+35)+31.25=397.92\ \mathrm V$.`,'The lower 15 Ω and 10 Ω are in series; treating all four resistors as parallel gives a wrong source voltage.','Voltmeter ≈ 206 V; battery emf ≈ 398 V.','meter',['Series: 45 Ω, 35 Ω','Branches: 25; 15; 15+10 Ω','A reads 1.25 A'],206.25,'V, voltmeter');
add(9,'26.8','Three resistors in parallel','Resistors 1.60 Ω, 2.40 Ω and 4.80 Ω connect in parallel to an ideal 28.0 V battery.','Find equivalent resistance, branch currents, total current, branch voltages and powers.','Every branch receives the same battery voltage. Ignore the unrelated image printed beside this question.',r`$R_{eq}^{-1}=1/1.60+1/2.40+1/4.80;\ I_i=V/R_i;\ P_i=V^2/R_i$.`,r`$R_{eq}=0.800\ \Omega;\ (I_1,I_2,I_3)=(17.5,11.7,5.83)\ \mathrm A;\ I_{total}=35.0\ \mathrm A$. Each voltage is 28.0 V; powers are $(490,327,163)\ \mathrm W$.`,'Branch currents sum to 35.0 A and powers sum to VI = 980 W.','0.800 Ω; 17.5, 11.7, 5.83 A; total 35.0 A; each 28 V; 490, 327, 163 W.','parallel',['28.0 V across each','1.60 Ω ; 2.40 Ω ; 4.80 Ω','Total current 35.0 A'],.8,'Ω');
add(9,'26.21','Brightness in series and parallel','Treat two bulbs as constant resistances 400 Ω and 800 Ω, supplied by 120 V.','For series and parallel, find currents, powers, total power and relative brightness.','Series shares current; parallel shares voltage. Brightness follows power in this model.',r`$I_s=120/(400+800);\ P_{s,i}=I_s^2R_i;\ I_{p,i}=120/R_i;\ P_{p,i}=120^2/R_i$.`,r`Series: each $I=0.100\ \mathrm A$, powers $4.00,8.00\ \mathrm W$, total $12.0\ \mathrm W$. Parallel: currents $0.300,0.150\ \mathrm A$, powers $36.0,18.0\ \mathrm W$, total $54.0\ \mathrm W$.`,'800 Ω is brighter in series; 400 Ω is brighter in parallel. Parallel gives greater combined output under the stated constant-resistance model.','Series: 12 W total, 800 Ω brighter. Parallel: 54 W total, 400 Ω brighter.','bulbs',['Series: same I','Parallel: same V','400 Ω and 800 Ω'],54,'W, parallel total');
add(9,'26.24','Two ideal sources','Three branches connect top/bottom nodes: a 10.0 V source (+ on top), a 30.0 Ω resistor, and a 20.0 Ω resistor above a 5.00 V source (+ on top).','Find current through each resistor and the 10 V battery.','The 10 V source fixes top-minus-bottom potential.',r`$I_{30}=10/30;\ I_{20}=(10-5)/20;\ I_{10V}=I_{30}+I_{20}$.`,r`$I_{30}=0.333\ \mathrm A$ downward; $I_{20}=0.250\ \mathrm A$ downward; $I_{10V}=0.583\ \mathrm A$ upward.`,'The smaller battery is being charged. Junction current is conserved: 0.583 = 0.333 + 0.250.','30 Ω: 0.333 A down; 20 Ω: 0.250 A down; 10 V source: 0.583 A up.','twosource',['Top minus bottom = 10 V','30 Ω branch','20 Ω then +5 V'],.333333,'A, 30 Ω branch');
add(9,'26.28','Three-branch circuit and node voltage','Top branch left→right: 2 Ω, 10 V source (+ left), point a, 3 Ω. Middle: 1 Ω, 5 V source (+ left), point b, 4 Ω. Bottom: 10 Ω.','Find branch currents and Vₐ − Vᵦ. Do only 26.28.','Assign all branch currents left-to-right; negative results reverse direction.',r`Let $D=V_L-V_R$. Then $I_t=(D-10)/5$, $I_m=(D-5)/5$, $I_b=D/10$ and $I_t+I_m+I_b=0$.`,r`$2(D-10)+2(D-5)+D=0\Rightarrow D=6.00\ \mathrm V$. Thus $(I_t,I_m,I_b)=(-0.800,+0.200,+0.600)\ \mathrm A$. $V_a-V_R=3I_t=-2.40\ \mathrm V$; $V_b-V_R=4I_m=0.800\ \mathrm V$.`,'Therefore Vab = −3.20 V. Both positive battery terminals are on the left; the polarity-reversal question 26.29 is excluded.','Top 0.800 A right→left; middle 0.200 A and bottom 0.600 A left→right; Vab = −3.20 V.','threebranch',['Top: 2 Ω, +10 V, a, 3 Ω','Middle: 1 Ω, +5 V, b, 4 Ω','Bottom: 10 Ω'],-3.2,'V, Vab');
add(9,'26.39','Voltmeter discharges a capacitor','Initially V₀ = 12.0 V. A 3.40 MΩ voltmeter reads 3.0 V after 4.00 s.','Find capacitance and time constant.','The voltmeter itself supplies the discharge path.',r`$V/V_0=e^{-t/\tau};\ \tau=t/\ln(V_0/V);\ C=\tau/R$.`,r`$\tau=4.00/\ln4=2.89\ \mathrm s;\ C=2.885/(3.40\times10^6)=0.849\ \mu\mathrm F$.`,'At one time constant the voltage is 36.8%, not 25%, of its starting value.','C = 0.849 µF; τ = 2.89 s.','decay',['V₀ = 12 V','V(4 s) = 3 V','τ = RC'],.849e-6,'F');
add(9,'26.43','Discharge of two capacitors','15.0 µF and 20.0 µF capacitors are parallel, initially at 45.0 V. Closing the switch discharges them through 50.0 Ω and 30.0 Ω in series.','Find time to reach 10.0 V and current then.','Combine capacitance in parallel and resistance in series.',r`$C=35\ \mu\mathrm F;\ R=80\ \Omega;\ \tau=RC;\ t=\tau\ln(45/10);\ I=10/R$.`,r`$\tau=2.80\ \mathrm{ms};\ t=4.21\ \mathrm{ms};\ I=0.125\ \mathrm A$.`,'Both capacitors always have the same voltage; discharge current flows from their positive terminals through the resistors.','4.21 ms; 0.125 A.','decay',['Cparallel = 35 µF','Rseries = 80 Ω','45 V → 10 V'],.00421,'s');
add(9,'26.51','Charging curve determines R','Uncharged C = 5.90 µF charges through R from a 28.0 V ideal source. At t = 3.00 ms, Q = 110 µC.','Find final charge, resistance and time to 99% charge.','Invert the charging exponential using the remaining uncharged fraction.',r`$Q_\infty=C\mathcal E;\ Q=Q_\infty(1-e^{-t/RC});\ RC=-t/\ln(1-Q/Q_\infty)$.`,r`$Q_\infty=165.2\ \mu\mathrm C;\ \tau=2.737\ \mathrm{ms};\ R=464\ \Omega;\ t_{99}=\tau\ln100=12.6\ \mathrm{ms}$.`,'99% charge takes 4.605 time constants; it never reaches exactly 100% in the ideal model.','165.2 µC; 464 Ω; 12.6 ms.','rise',['Q∞ = 165.2 µC','Q(3 ms) = 110 µC','τ = RC'],464,'Ω');
add(9,'25.59','Supplement: tapered resistor','A truncated cone of height h has end radii r₁ and r₂ and uniform resistivity ρ. Current travels along its axis.','Find resistance using thin slices; check the cylinder limit.','Slices across the axis carry the same current, so their resistances add in series.',r`$r(x)=r_1+(r_2-r_1)x/h;\ dR=\rho\,dx/[\pi r(x)^2]$.`,r`$R=\frac{\rho h}{\pi(r_2-r_1)}(\frac1{r_1}-\frac1{r_2})=\frac{\rho h}{\pi r_1r_2}$.`,'When r₁ = r₂ = r, the limit is ρh/(πr²). This uses the thin-slice axial-current model requested by the problem.','R = ρh/(πr₁r₂).','cone',['End radius r₁','End radius r₂','Axial length h']);
add(10,'27.1','Magnetic force on a negative charge','q = −1.24 × 10⁻⁸ C; v = (4.19 × 10⁴ i − 3.85 × 10⁴ j) m/s.','Find F for (a) B = 1.40 i T and (b) B = 1.40 k T.','Compute v × B first, then multiply by the negative charge.',r`$\mathbf F=q\mathbf v\times\mathbf B$. For (a), $\mathbf v\times\mathbf B=-v_y B_x\mathbf k$. For (b), it is $B_z(v_y\mathbf i-v_x\mathbf j)$.`,r`(a) $\mathbf F=-6.68\times10^{-4}\mathbf k\ \mathrm N$. (b) $\mathbf F=(6.68\times10^{-4}\mathbf i+7.27\times10^{-4}\mathbf j)\ \mathrm N$.`,'Each result is perpendicular to both velocity and field. A negative charge reverses the right-hand-rule direction.','(a) −6.68 × 10⁻⁴ k N; (b) (6.68 i + 7.27 j) × 10⁻⁴ N.','axes',['q is negative','v in xy-plane','F = q(v × B)'],-6.68e-4,'N, Fz in part (a)');
add(10,'27.4','Magnetic acceleration','m = 1.81 × 10⁻³ kg; q = +1.22 × 10⁻⁸ C; v = 3.00 × 10⁴ j m/s; B = (1.63 i + 0.980 j) T.','Find acceleration magnitude and direction.','The field component parallel to v produces no force.',r`$\mathbf a=(q/m)\mathbf v\times\mathbf B=-(qv_yB_x/m)\mathbf k$.`,r`$|a|=(1.22\times10^{-8})(3.00\times10^4)(1.63)/(1.81\times10^{-3})=0.330\ \mathrm{m/s^2}$.`,'j × i = −k, so acceleration is into the xy-plane for positive q.','0.330 m/s² along −k.','axes',['v along +y','Bx = 1.63 T','a along −z'],.330,'m/s²');
add(10,'27.7','Recover magnetic-field components','q = +7.80 µC; v = −3.80 × 10³ j m/s; F = (7.60 × 10⁻³ i − 5.20 × 10⁻³ k) N.','Find determined B components, identify any undetermined component, and calculate B·F and their angle.','A force measurement cannot reveal the component of B parallel to v.',r`$F_x=qv_yB_z;\ F_z=-qv_yB_x;\ F_y=0$.`,r`$B_z=0.00760/[7.80\times10^{-6}(-3800)]=-0.256\ \mathrm T;\ B_x=-(-0.00520)/[7.80\times10^{-6}(-3800)]=-0.175\ \mathrm T$. $B_y$ is unrestricted; $\mathbf B\cdot\mathbf F=B_xF_x+B_zF_z=0$.`,'B and F are perpendicular (90°) regardless of By. Do not assume By = 0 just because it is undetermined.','Bx = −0.175 T; Bz = −0.256 T; By undetermined; B·F = 0, angle 90°.','axes',['v along −y','F has x,z components','By is undetermined'],-.25641,'T, Bz');
add(10,'27.10','Magnetic flux through an xy square','Square side 0.0340 m lies in the xy-plane; B = (0.200 i + 0.300 j − 0.500 k) T.','Find magnetic-flux magnitude.','Only the normal component Bz crosses the square.',r`$\Phi=\mathbf B\cdot\mathbf A=B_zs^2$ for the +z normal.`,r`$\Phi=(-0.500)(0.0340)^2=-5.78\times10^{-4}\ \mathrm{Wb}$, so $|\Phi|=5.78\times10^{-4}\ \mathrm{Wb}$.`,'The x and y components run along the surface and contribute no flux.','Magnitude 5.78 × 10⁻⁴ Wb.','flux',['Surface: xy-plane','Normal: +z','Bz = −0.500 T'],5.78e-4,'Wb, magnitude');
add(10,'27.19','Cosmic-ray semicircle','Particles have |q| = 3e, m = 12mₚ and enter downward into B = 0.250 T out of the page. They curve to the right through a semicircle of diameter 0.950 m.','Find speed and charge sign, assess gravity, and compare entry/exit speeds.','The radius is half the diameter; magnetic force supplies centripetal acceleration.',r`$|q|vB=mv^2/r;\ r=0.475\ \mathrm m;\ v=|q|Br/m$.`,r`$v=2.84\times10^6\ \mathrm{m/s}$. For downward v and outward B, positive charge would bend left: the observed charge is $-3e$. $F_B/(mg)=v^2/(rg)=1.74\times10^{12}$.`,'Gravity is negligible. Magnetic force does no work, so entry and exit speeds are equal.','2.84 × 10⁶ m/s; negative charge; negligible gravity; unchanged speed.','semipath',['Enter downward','B out of page','Diameter = 0.950 m'],2.84e6,'m/s');
add(10,'27.21','Deuteron orbit','Deuteron mass 3.34 × 10⁻²⁷ kg and charge +e; orbit radius 6.96 mm in B = 2.50 T.','Find speed, half-orbit time, and accelerating potential magnitude from rest.','Combine circular motion with kinetic energy gained from voltage.',r`$v=qBr/m;\ t_{1/2}=\pi r/v=\pi m/(qB);\ |\Delta V|=mv^2/(2q)$.`,r`$v=8.35\times10^5\ \mathrm{m/s};\ t_{1/2}=2.62\times10^{-8}\ \mathrm s;\ |\Delta V|=7.26\times10^3\ \mathrm V$.`,'The positive deuteron must move through a potential drop of 7.26 kV to gain this energy.','8.35 × 10⁵ m/s; 26.2 ns; 7.26 kV drop.','orbit',['q = +e','r = 6.96 mm','B = 2.50 T'],8.35e5,'m/s');
add(10,'27.24','Quarter-circle proton path','Protons at 1.20 km/s turn 90° while travelling arc length 1.18 cm in a perpendicular magnetic field.','Find magnetic-field magnitude.','The given distance is an arc length, not a radius.',r`$s=\pi r/2;\ r=2s/\pi;\ B=m_pv/(er)$.`,r`$r=2(0.0118)/\pi=0.00751\ \mathrm m;\ B=1.67\times10^{-3}\ \mathrm T$.`,'For a proton entering rightward and turning upward, B points into the page.','1.67 mT.','quarterpath',['Arc s = 1.18 cm','Turn = 90°','B into page'],.00167,'T');
add(10,'27.27','Crossed-field selector','v = +5.85 × 10³ j m/s; B = −1.35 k T. Charges are (a) +0.640 nC and (b) −0.320 nC.','Find E needed for undeflected motion in each case.','Zero net force requires E = −v × B for either nonzero charge.',r`$q(\mathbf E+\mathbf v\times\mathbf B)=0;\ \mathbf v\times\mathbf B=-(5.85\times10^3)(1.35)\mathbf i$.`,r`$\mathbf E=+7.90\times10^3\mathbf i\ \mathrm{N/C}$ for both particles.`,'Both forces reverse with charge sign, leaving the same cancellation condition.','Both require E = +7.90 × 10³ i N/C.','axes',['v along +y','B along −z','E along +x'],7.90e3,'N/C, Ex');
add(10,'27.29','Alpha-particle velocity selector','Alpha q = +2e, m = 6.64 × 10⁻²⁷ kg accelerates from rest through 1.75 kV. It enters rightward between plates separated 8.20 mm with 150 V across them; lower plate positive.','Find the magnetic field for no deflection.','Find speed from accelerating voltage, then cancel electric and magnetic forces.',r`$v=\sqrt{2qV_{acc}/m};\ E=150/0.00820;\ B=E/v$.`,r`$v=4.11\times10^5\ \mathrm{m/s};\ E=1.83\times10^4\ \mathrm{V/m}$ upward; $B=0.0445\ \mathrm T$.`,'B must point out of the page: rightward v × outward B points downward, cancelling the upward electric force. Plate area is not needed.','0.0445 T out of the page.','selector',['v →','E ↑ (lower plate +)','B out of page'],.0445,'T');
add(11,'27.37','Lift-off of a conducting bar','Bar L = 0.500 m, mass 0.750 kg, B = 0.450 T into the page; current runs rightward. Series resistance starts at 25.0 Ω, then falls to 2.0 Ω.','Find maximum battery voltage before lift-off, then initial acceleration after resistance falls.','At lift-off magnetic force equals weight; afterward subtract weight from magnetic force.',r`$I_{max}=mg/(LB);\ V_{max}=I_{max}R;\ a=[(V_{max}/R')LB-mg]/m$.`,r`$I_{max}=32.7\ \mathrm A;\ V_{max}=817\ \mathrm V$. Then $F_B=91.9\ \mathrm N$, $mg=7.35\ \mathrm N$, and $a=112.7\ \mathrm{m/s^2}$ upward.`,'This is the initial acceleration while current still flows through the contacts; the circuit breaks when the bar lifts off.','Maximum ≈ 817 V; initial acceleration ≈ 113 m/s² upward.','bar',['I → ; B into page','Magnetic force ↑','Weight mg ↓'],817,'V');
add(11,'27.41','Torque about a loop hinge','Rectangle abcd: vertical ab = cd = 0.200 m; horizontal bc = da = 0.350 m. Clockwise current 5.00 A; B = 1.20 T rightward; hinge along left side ab.','Find force directions, identify which force torques the hinge, and calculate torque.','Parallel sides feel zero magnetic force; a force at the hinge has zero lever arm.',r`$\mathbf F=I\mathbf L\times\mathbf B$. On ab force is into the page; on cd it is out. $F_{bc}=F_{da}=0$.`,r`$F_{cd}=IB(0.200)=1.20\ \mathrm N;\ \tau=(0.350)(1.20)=0.420\ \mathrm{N\,m}$. $F_{ab}=1.20\ \mathrm N$ but its hinge lever arm is zero.`,'The right side cd swings out of the page. Net force is zero, but the force couple produces nonzero torque.','Only cd torques the hinge: 1.20 N outward; torque 0.420 N m.','hinge',['ab: hinge, force into page','cd: force out of page','B → ; I clockwise'],.420,'N m');
add(11,'27.42','Rotating a current loop','Loop 0.220 m × 0.350 m, I = 1.95 A counterclockwise, B = 1.50 T into page. Initially loop plane is perpendicular to B; then rotate 30° with left side outward and right side inward.','Find net force and torque before and after rotation.','A closed loop in uniform B has zero net force; torque is μ × B.',r`$\mu=IA;\ |\tau|=IAB\sin\theta$, where θ is between the loop normal and B. Initially $\theta=180^\circ$; afterward $\theta=150^\circ$.`,r`Initially $F_{net}=0,\tau=0$. After rotation $F_{net}=0$ and $|\tau|=(1.95)(0.220)(0.350)(1.50)\sin150^\circ=0.113\ \mathrm{N\,m}$.`,'The initial magnetic moment is opposite B (unstable equilibrium). After the stated rotation the torque continues that rotation, with left side moving further out.','Both net forces zero; torque 0 initially, then 0.113 N m continuing the rotation.','loop',['Initial μ out; B in','Rotate 30°','|τ| = IAB sin θ'],.113,'N m, rotated');
add(11,'27.56','Cyclotron energy limit','Cyclotron B = 0.85 T, maximum orbit radius 0.40 m. Proton q = 1.60 × 10⁻¹⁹ C, m = 1.67 × 10⁻²⁷ kg. Alpha q = 3.20 × 10⁻¹⁹ C, m = 6.64 × 10⁻²⁷ kg.','Find proton maximum energy in J/eV, period, B needed to double energy, and alpha maximum energy at 0.85 T.','Use the orbit radius to obtain speed, then kinetic energy.',r`$K_{max}=q^2B^2R^2/(2m);\ T=2\pi m/(qB);\ B'=\sqrt2B$.`,r`Proton: $K=8.86\times10^{-13}\ \mathrm J=5.54\times10^6\ \mathrm{eV}$; $T=7.72\times10^{-8}\ \mathrm s$; $B'=1.20\ \mathrm T$. Alpha: $K=8.91\times10^{-13}\ \mathrm J=5.57\ \mathrm{MeV}$.`,'The alpha energy is almost the same: its charge squared is four times greater and mass approximately four times greater. Nonrelativistic model.','Proton 5.54 MeV; period 77.2 ns; doubling requires 1.20 T; alpha 5.57 MeV.','orbit',['Maximum R = 0.40 m','B = 0.85 T','K ∝ q²B²R²/m'],5.54e6,'eV, proton energy');
add(11,'27.65','Rail-gun acceleration','A bar of mass m and length L bridges horizontal rails in uniform vertical field B, carrying constant current I across the bar as shown in the handout. Ignore friction and gravity for the motion.','Derive force and distance from rest to speed v; evaluate for 11.2 km/s, B = 0.80 T, I = 2.0 × 10³ A, m = 25 kg, L = 0.50 m.','Magnetic force is constant, so use constant acceleration or work–energy.',r`$F=ILB;\ a=ILB/m;\ \tfrac12mv^2=Fd\Rightarrow d=mv^2/(2ILB)$.`,r`$F=(2000)(0.50)(0.80)=800\ \mathrm N;\ a=32\ \mathrm{m/s^2};\ d=25(11200)^2/(1600)=1.96\times10^6\ \mathrm m$.`,'Force points along the rails away from the source for the shown current. The 1960 km distance illustrates the limits of this simplified launch model.','F = ILB along rails; d = mv²/(2ILB); example distance 1.96 × 10⁶ m.','rail',['Across-bar current I','Vertical B','Force along rails →'],1.96e6,'m');
add(11,'27.69','Suspended loop in equilibrium','Loop width 6.00 cm, height 8.00 cm, mass per length 0.15 g/cm, current 8.2 A as in handout. Hinge is its upper 6 cm side; plane tilts 30° from yz-plane. B is parallel to y.','Find magnitude and direction of B needed for equilibrium.','Balance gravity’s torque about the hinge against magnetic torque.',r`$m=(0.15)(2)(6+8)\ \mathrm g=0.00420\ \mathrm{kg};\ A=0.06(0.08)$. $mg(0.040)\sin30^\circ=IAB\cos30^\circ$.`,r`$B=\frac{(0.00420)(9.80)(0.040)\tan30^\circ}{(8.2)(0.00480)}=0.0242\ \mathrm T$.`,'B points upward along +y for the shown current. The wire loop’s centre of mass lies halfway down; counting only the bottom wire would underestimate gravity torque.','0.0242 T along +y.','tiltedloop',['Hinge: 6.00 cm side','Height 8.00 cm','Tilt 30°; B ↑'],.0242,'T');
add(12,'28.29','Force between opposite currents','Two long wires 0.400 m apart carry 5.00 A rightward and 2.00 A leftward. Consider 1.20 m of each wire.','Find the force and whether it attracts; then double both currents.','One wire’s field acts on the other: F/L = μ₀I₁I₂/(2πd).',r`$F=\mu_0I_1I_2L/(2\pi d)$.`,r`$F=(2\times10^{-7})(5)(2)(1.20)/0.400=6.00\times10^{-6}\ \mathrm N$. Doubling both currents gives $4F=2.40\times10^{-5}\ \mathrm N$.`,'Opposite currents repel. The two forces have equal magnitudes and opposite directions.','6.00 µN repulsive; doubled currents give 24.0 µN.','wires',['I₁ = 5 A →','I₂ = 2 A ←','d = 0.400 m'],6e-6,'N');
add(12,'28.34','Field from a semicircular wire','Current I enters from the left, runs clockwise around an upper semicircle of radius R, then exits rightward along the same diameter line. P is the arc centre.','Find B at P, including straight sections.','Straight radial sections have dl parallel to the vector toward P and contribute zero.',r`$dB=\mu_0 I\,dl/(4\pi R^2);\ \int dl=\pi R$.`,r`$B=\mu_0 I(\pi R)/(4\pi R^2)=\mu_0I/(4R)$.`,'Clockwise current makes B point into the page. This is half the field of a complete loop of the same R and I.','B = μ₀I/(4R), into the page.','semicircle',['Upper arc: clockwise I','Radius R','B at P: into page']);
add(12,'28.40','Ampère integrals','I₁ = 4 A into page, I₂ = 6 A out, I₃ = 2 A out. Counterclockwise paths: a encloses none; b only I₁; c I₁+I₂; d all three.','Find ∮B·dl for each path.','Counterclockwise traversal makes outward current positive.',r`$\oint\mathbf B\cdot d\mathbf l=\mu_0I_{enc};\ (I_a,I_b,I_c,I_d)=(0,-4,+2,+4)\ \mathrm A$.`,r`Integrals: $(0,-5.03\times10^{-6},+2.51\times10^{-6},+5.03\times10^{-6})\ \mathrm{T\,m}$.`,'A zero integral does not imply zero field everywhere on the path. Shape and perimeter do not affect this steady-current result.','a: 0; b: −5.03 × 10⁻⁶; c: +2.51 × 10⁻⁶; d: +5.03 × 10⁻⁶ T m.','ampere',['I₁: 4 A into page','I₂: 6 A out','I₃: 2 A out'],-5.03e-6,'T m, path b');
add(12,'28.43','Coaxial cable field','Solid conductor radius a and outer tube inner/outer radii b,c carry equal currents I in opposite directions, uniformly distributed.','Derive B for a < r < b and r > c.','Use circular Amperian paths and the net enclosed current.',r`$B(2\pi r)=\mu_0I_{enc}$.`,r`For $a<r<b$, $I_{enc}=I$, so $B=\mu_0 I/(2\pi r)$. For $r>c$, $I_{enc}=I-I=0$, so $B=0$.`,'Between conductors, field is azimuthal with direction from the inner-current right-hand rule. Exterior cancellation depends on equal opposite currents and ideal long coaxial geometry.','Between: μ₀I/(2πr); outside: 0.','coax',['Inner radius a','Tube radii b,c','Equal opposite currents']);
add(12,'28.57','Where two-wire fields cancel','Long wires 0.400 m apart carry 25.0 A and 75.0 A.','Find all zero-field locations for same-direction and opposite-direction currents.','Equal magnitudes are not enough: fields must oppose at the candidate location.',r`For same directions between wires: $25/x=75/(0.400-x)$. For opposite directions outside the 25 A wire: $25/s=75/(s+0.400)$.`,r`Same direction: $x=0.100\ \mathrm m$ from 25 A toward 75 A. Opposite directions: $s=0.200\ \mathrm m$ outside the 25 A side, 0.600 m from 75 A.`,'Each solution extends along a line parallel to the wires. There is no cancellation outside for same directions or between for opposite directions.','Same: 0.100 m between; opposite: 0.200 m outside the 25 A wire.','cancel',['25 A at x = 0','75 A at x = 0.400 m','Zero: x = +0.100 or −0.200'],.100,'m from 25 A, same-direction case');
add(12,'28.61','Overhead bus cables','Bus input power 65 hp, cable voltage 600 V, separation 0.55 m. Use 1 hp = 746 W.','Find current and force per unit length.','Use input power P = VI, then the parallel-wire force formula.',r`$I=P/V;\ F/L=\mu_0 I^2/(2\pi d)$.`,r`$P=65(746)=48490\ \mathrm W;\ I=80.8\ \mathrm A;\ F/L=(2\times10^{-7})(80.8)^2/0.55=2.38\times10^{-3}\ \mathrm{N/m}$.`,'The sheet calls it “attractive,” but supply and return currents run in opposite directions and repel. The magnitude above is unchanged.','80.8 A; 2.38 × 10⁻³ N/m, repulsive for supply/return cables.','wires',['Supply current →','Return current ←','d = 0.55 m'],80.8,'A');
add(12,'28.62','Field on the symmetry axis','Wires at (0,+a) and (0,−a) carry equal I, respectively out of and into the page. Observe P = (x,0).','Draw each field and net field, derive B(x), graph it, find its maximum and far-field limit.','The y components cancel; the x components add.',r`$r=\sqrt{x^2+a^2};\ B_{each}=\mu_0I/(2\pi r);\ B_x=2B_{each}(a/r)$.`,r`$\mathbf B=\frac{\mu_0Ia}{\pi(x^2+a^2)}\mathbf i$. Maximum at $x=0$: $B_{max}=\mu_0I/(\pi a)$. For $|x|\gg a$, $B\approx\mu_0Ia/(\pi x^2)$.`,'The graph is even in x, peaks at zero and falls toward zero on either side. At x > 0 the upper wire field tilts up-right and lower wire field down-right.','B = μ₀Ia/[π(x²+a²)] along +x; peak at x = 0; far field ∝ 1/x².','fieldgraph',['Upper wire: I out','Lower wire: I in','Net B along +x']);
add(12,'28.64','Force on a loop beside a wire','Long wire carries 14.0 A rightward. Loop below it carries 5.00 A clockwise, horizontal length 0.200 m. Top edge is 0.0260 m from wire; bottom edge is 0.100 m from wire.','Find net force on the loop.','Opposing horizontal-side forces differ because B decreases with distance; vertical-side forces cancel.',r`$F_{net}=\frac{\mu_0 I_wI_l L}{2\pi}(1/r_{top}-1/r_{bottom})$.`,r`$F_{net}=(2\times10^{-7})(14)(5)(0.200)(1/0.0260-1/0.100)=7.97\times10^{-5}\ \mathrm N$.`,'The near edge has current parallel to the wire and is attracted more strongly, so net force is upward toward the wire. The 10.0 cm label is wire-to-bottom distance.','7.97 × 10⁻⁵ N toward the wire.','wireloop',['Top gap 2.60 cm','Bottom distance 10.0 cm','Loop length 20.0 cm'],7.97e-5,'N');
add(12,'28.65','Suspended current-carrying wires','Two opposite-current wires hang from common supports on 0.0400 m cords, each 6.00° from vertical. Mass per wire length λ = 0.0125 kg/m.','Find the equal current magnitude.','Magnetic repulsion balances the horizontal tension component.',r`$d=2\ell\sin\theta;\ (F/L)=\lambda g\tan\theta=\mu_0I^2/(2\pi d)$.`,r`$d=0.00836\ \mathrm m;\ I=\sqrt{\lambda g\tan6^\circ\,(2\pi d)/\mu_0}=23.2\ \mathrm A$.`,'Use the separation of both wires, 2ℓ sinθ, not the displacement of only one.','23.2 A per wire, in opposite directions.','hangingwires',['Each cord ℓ = 4.00 cm','Each angle θ = 6°','d = 2ℓ sin θ'],23.2,'A');
add(12,'28.72','Cancel a loop’s centre field','Clockwise circular loop radius R carries I₂. Its centre is distance D above a long horizontal wire carrying I₁.','Find I₁ magnitude and direction for zero field at the loop centre.','The loop’s inward field must be cancelled by the wire’s outward field.',r`$\mu_0I_1/(2\pi D)=\mu_0I_2/(2R)$.`,r`$I_1=\pi D I_2/R$. The wire current must run rightward.`,'For a rightward wire current the field above it is out of the page. Cancellation is at the centre, not throughout the loop area.','I₁ = πDI₂/R, rightward.','loopwire',['Clockwise I₂','Centre height D','Wire I₁ →']);
add(13,'29.25','Motional voltage along a rod','Rod a→b points up-right, length 0.300 m. It moves down-right perpendicular to itself at 5.00 m/s through B = 0.450 T into page.','Find voltage magnitude, higher-potential end, internal E and positive end; then voltage for motion along the rod or out of the page.','Charge separation balances qE against q(v × B).',r`$|\Delta V|=BLv;\ \mathbf E=-\mathbf v\times\mathbf B;\ E=vB$.`,r`$|\Delta V|=(0.450)(0.300)(5.00)=0.675\ \mathrm V$. Positive charges collect at b; b is higher. $E=2.25\ \mathrm{V/m}$ from b to a. Along-rod and out-of-page motions each give zero end-to-end voltage.`,'For along-rod motion the magnetic force is perpendicular to the rod; for motion parallel/antiparallel to B it vanishes.','0.675 V; b positive and higher; E = 2.25 V/m toward a; both alternate motions give 0 V.','movingrod',['a lower-left; b upper-right','v down-right','B into page'],.675,'V');
add(13,'29.26','Loop leaving a field','Loop 0.300 m wide × 0.400 m tall moves right at 0.0200 m/s out of a region with B = 1.25 T into page.','Find emf when fully inside, partly inside and fully outside.','Induced emf requires changing flux, not merely nonzero flux.',r`$|\mathcal E|=|d\Phi/dt|=B|dA_{inside}/dt|$. During exit, $|dA/dt|=hv$.`,r`Inside: $0$. During exit: $\mathcal E=(1.25)(0.400)(0.0200)=0.0100\ \mathrm V$. Outside: $0$.`,'During exit induced current is clockwise to reinforce the diminishing inward flux. Use the 0.400 m side transverse to motion.','0 V; 10.0 mV during exit; 0 V.','exitingloop',['Height = 0.400 m','v → at 0.0200 m/s','B in page, left of boundary'],.01,'V, during exit');
add(13,'29.29','Sliding rod and energy conservation','Rod length 0.500 m slides right at 7.50 m/s along closed rails; B = 0.800 T into page; circuit resistance 1.50 Ω. Top rod end a, bottom b.','Find induced emf, rod current direction, required external force, and mechanical/electrical powers.','Lenz’s law gives magnetic drag; an external force maintains speed.',r`$\mathcal E=BLv;\ I=\mathcal E/R;\ F_{ext}=ILB;\ P_{mech}=F_{ext}v;\ P_{heat}=I^2R$.`,r`$\mathcal E=3.00\ \mathrm V;\ I=2.00\ \mathrm A$ from b to a; $F_{ext}=0.800\ \mathrm N$ rightward. Both powers equal $6.00\ \mathrm W$.`,'The magnetic force on the rod is leftward. External mechanical work supplies the resistive heat.','3.00 V; 2.00 A b→a; external force 0.800 N rightward; both powers 6.00 W.','slidingrod',['a at top; b at bottom','v → ; B into page','Current in rod ↑'],3,'V');
add(13,'29.42','Displacement current between plates','Circular air-capacitor plates have radius R = 0.0400 m; charging current I = 0.520 A. Assume uniform field away from edges.','Find displacement current density, dE/dt, and B at radii 0.0200 m and 0.0100 m.','Conduction current equals total displacement current; an interior loop encloses only an area fraction.',r`$J_D=I/(\pi R^2);\ dE/dt=J_D/\varepsilon_0;\ B(2\pi r)=\mu_0J_D\pi r^2$.`,r`$J_D=103\ \mathrm{A/m^2};\ dE/dt=1.17\times10^{13}\ \mathrm{V/(m\,s)}$. $B=\mu_0J_Dr/2$: at 2 cm, $1.30\ \mu\mathrm T$; at 1 cm, $0.650\ \mu\mathrm T$.`,'Inside the plate radius B grows linearly with r; its direction circles the charging axis by the right-hand rule.','103 A/m²; 1.17 × 10¹³ V/(m s); 1.30 µT and 0.650 µT.','coax',['Plate radius R = 4 cm','Amperian radius r < R','Uniform JD through plate'],103.45,'A/m²');
add(13,'30.9','Inductance and flux per turn','Current increases at 0.0640 A/s and induced emf magnitude is 0.0160 V. Solenoid has N = 400 turns; consider I = 0.720 A.','Find inductance and average flux per turn.','Flux linkage is NΦ = LI, not simply Φ = LI.',r`$L=|\mathcal E|/|dI/dt|;\ \Phi=LI/N$.`,r`$L=0.0160/0.0640=0.250\ \mathrm H;\ \Phi=(0.250)(0.720)/400=4.50\times10^{-4}\ \mathrm{Wb}$.`,'The induced emf opposes the current increase; the reported emf and flux here are magnitudes.','0.250 H; 4.50 × 10⁻⁴ Wb per turn.','inductor',['N = 400','I increasing','NΦ = LI'],.250,'H');
add(13,'30.11','Polarity of a decreasing-current inductor','L = 0.260 H; current runs from b to a (right-to-left) and decreases at 0.0180 A/s.','Find induced emf and higher-potential end.','An inductor opposes the decrease by sustaining current in its original direction.',r`$\mathcal E=-L\,di/dt$ with positive current chosen b→a.`,r`$\mathcal E=-(0.260)(-0.0180)=+0.00468\ \mathrm V$ in the b→a direction. Therefore $V_a-V_b=+4.68\ \mathrm{mV}$.`,'The inductor acts as a source while returning stored magnetic energy; a is at higher potential.','4.68 mV; a is higher than b.','inductor',['a at left; b at right','Current b → a, decreasing','Induced emf sustains current'],.00468,'V, Va − Vb');
add(13,'30.23','Current growth in an RL circuit','Battery emf 6.00 V; series inductor L = 2.50 H and resistance R = 8.00 Ω; initial current zero.','Find initial di/dt, di/dt at I = 0.500 A, I at 0.250 s, and final current.','Apply the loop rule including the inductor voltage.',r`$\mathcal E-IR=L\,dI/dt;\ I(t)=(\mathcal E/R)(1-e^{-tR/L})$.`,r`Initially $dI/dt=6/2.50=2.40\ \mathrm{A/s}$. At 0.500 A, $dI/dt=(6-4)/2.50=0.800\ \mathrm{A/s}$. $I(0.250)=0.750(1-e^{-0.8})=0.413\ \mathrm A$. $I_\infty=0.750\ \mathrm A$.`,'The inductor limits the initial rate of change; at steady state its ideal inductive voltage is zero.','2.40 A/s; 0.800 A/s; 0.413 A; final 0.750 A.','rise',['L = 2.50 H','R = 8.00 Ω','I∞ = 0.750 A'],.413,'A at 0.250 s');
add(13,'30.25','Half-current versus half-energy','Initially open series circuit: 35.0 V ideal battery, R = 50.0 Ω and ideal L = 1.25 mH. Close the switch at t = 0.','Find times to half maximum current and half maximum magnetic energy.','Energy is proportional to current squared, so half-energy requires I/I∞ = 1/√2.',r`$\tau=L/R;\ I/I_\infty=1-e^{-t/\tau};\ U/U_\infty=(I/I_\infty)^2$.`,r`$\tau=25.0\ \mu\mathrm s;\ t_{I/2}=\tau\ln2=17.3\ \mu\mathrm s;\ t_{U/2}=-\tau\ln(1-1/\sqrt2)=30.7\ \mu\mathrm s$.`,'Half-energy occurs later than half-current: half-current stores only one-quarter of maximum energy.','17.3 µs to half-current; 30.7 µs to half-energy.','rise',['τ = L/R = 25 µs','Half I: I/I∞ = 0.5','Half U: I/I∞ = 0.707'],17.3e-6,'s, half-current');
const sources=require('./physics-homework-sources.json'), draw=require('./physics-homework-diagrams.cjs');
for(const q of out){q.source=sources[q.homework===9&&q.problem==='25.59'?'9-supplement':q.homework].url;q.drawing=draw(q);q.caption='Diagram for '+q.problem+': '+q.labels.join('; ')+'.';delete q.kind;delete q.labels;}

